pub fn infer(ctx: &Ctx, env: &Env, term: &TermRef) -> Result<ValueRef, TypeError> {
    match term.as_ref() {
        Term::Var(i) => ctx.iter().nth_back(*i).cloned().ok_or(TypeError::UnboundVar),

        Term::Lambda(_) => Err(TypeError::CannotInferLambda),

        Term::Apply(func, arg) => infer(ctx, env, func).and_then(|func_ty| match func_ty.as_ref() {
