// Term gains one variant:
Ann(TermRef, TermRef),   // ascription: term at a claimed type

// vocabulary helper:
pub fn ann(term: TermRef, ty: TermRef) -> TermRef {
    Rc::new(Term::Ann(term, ty))
}

// eval — annotations carry no computation; erase:
Term::Ann(t, _) => eval(env, t),

// infer — the ascription rule:
Term::Ann(t, ty) => {
    infer_universe(ctx, env, ty)?;        // the claimed type must be a type
