    //   fn(A,x,y,z,e1,e2,P,px){ e2(P)( e1(P)(px) ) }
    let proof = lambda(lambda(lambda(lambda(lambda(lambda(lambda(lambda(
        apply(
            apply(var(2), var(1))),                       // e2 P
            apply(apply(var(3), var(1))), var(0))),       // e1 P px
        ))))))));

    assert!(certify(&law, &proof).is_ok());
}
